"""The deliberate defects, and which tests ought to object to each.

Weighted toward decisions whose failure is SILENT and expensive. A crash gets
noticed; an opt-out that stops matching, a bounce counted against the wrong
cohort, or an erasure that quietly leaves data behind do not.

`tests` is deliberately narrow. Running the whole suite for each of 230
mutations would take many hours, and a mutation caught by an unrelated test tells you
nothing about whether the behaviour is actually defended. If a mutation
survives its own tests, widen it and re-run before concluding anything.
"""

