# There is no tests/test_agent.py, tests/test_warmup.py, tests/test_verification.py
# or tests/test_analytics.py in this repo, and five mutations named them. pytest
# exits 4 on a path it cannot find, the runner then read any non-zero exit as
# "the suite objected", and all five were reported CAUGHT without a single test
# ever being collected. (It now skips a mutation whose test file is missing and
# counts only exit 1 as CAUGHT.) Anchors are not the only thing that drifts; the coverage
# claim drifts too, and it fails in the direction that looks like health.

